def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def segments(n, separators):
        result, start = [], 0
        for x in separators:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < n:
            result.append((start, n))
        return result

    row_parts = segments(h, sep_rows)
    col_parts = segments(w, sep_cols)
    panels = []
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            count = sum(grid[r][c] != background
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            panels.append((r0, r1, c0, c1, count))

    source = max(panels, key=lambda p: p[4])
    sr0, sr1, sc0, sc1, count = source
    if count == 0:
        return [row[:] for row in grid]

    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]
    out = [row[:] for row in grid]
    for r0, r1, c0, c1, panel_count in panels:
        if (r0, r1, c0, c1) == (sr0, sr1, sc0, sc1):
            continue
        if panel_count == 0 and r1 - r0 == len(pattern) and c1 - c0 == len(pattern[0]):
            for i in range(r1 - r0):
                out[r0 + i][c0:c1] = pattern[i][:]
    return out
